#include "ksStatePresetAddressTask.h"
#include <vector>
#include <utility>
#include <iostream>
#include <stdexcept>
using T=ks::StatePresetAddressTask;void check(bool b,const char* w){if(!b)throw std::runtime_error(w);}
int main(){try{uint64_t cases=0;for(bool overlay:{false,true})for(unsigned bank=0;bank<256;++bank)for(unsigned program=0;program<256;++program){T task(overlay?T::Kind::Overlay:T::Kind::Current);unsigned reads=0,children=0,clocks=0;const unsigned storeClocks=program&3,index=(bank*257+program*13)&65535;std::vector<std::pair<T::Write,unsigned>> writes;auto read=[&](T::Read r)->unsigned{++reads;return r==T::Read::Bank?bank:program;};auto write=[&](T::Write w,uint8_t v){writes.emplace_back(w,v);};while(!task.complete()){if(task.awaitingIndex()){++children;check(task.resumeIndex(index),"Address index child rejected");continue;}const auto c=task.nextClocks(storeClocks),before=reads;const auto stores=writes.size();check(!task.advanceBefore(c-1,read,write,storeClocks)&&reads==before&&writes.size()==stores,"Address early observation");check(task.advanceBefore(c,read,write,storeClocks)==c,"Address admission differs");clocks+=c;}
 const bool available=!overlay||bank>4&&program!=49;check(task.available()==available&&(!available||task.address()==0x820000+index*256),"Address availability/offset differs");check(children==unsigned(available)&&reads==unsigned(overlay)*(bank>4?2:1)&&writes==(overlay&&available?std::vector<std::pair<T::Write,unsigned>>{{T::Write::Alias,49},{T::Write::Restore,program}}:std::vector<std::pair<T::Write,unsigned>>{}),"Alias temporary program restoration/order differs");const unsigned expected=!overlay?84:bank<=4?63:program==49?84:160+2*storeClocks;if(clocks!=expected){std::cerr<<"overlay="<<overlay<<" bank="<<bank<<" program="<<program<<" clocks="<<clocks<<" expected="<<expected<<'\n';throw std::runtime_error("Address clocks differ");}check(!task.resumeIndex(0),"Address restarted");++cases;}
std::cout<<"PASS: "<<cases<<" full current/alias preset address jobs,allbank+program pairs/optional conditions/byte wrap,temporary alias restore/typed index child/exact clocks/deadlines\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
